Q("C", 10, [P("Which one of the following statements is NOT part of the neutral paradigm in ecology?")],
  ["All individuals in the community have equal fitness and competitive ability.", "Loss of competing species to extinction is through a slow, random process.", "Diversity is maintained by speciation rates counteracting extinction rates.", "Ecological drift results in stable coexistence of a given set of species."],
  E("In Hubbell's (2001) unified neutral theory, species are ecologically equivalent, so abundances perform a random walk (ecological drift). Drift leads to slow, random extinction, never to stable coexistence. Stability would require stabilising niche differences, which the neutral model explicitly lacks.",
    {"1": "This is the core neutrality (per-capita equivalence) assumption.", "2": "Under drift, extinction is slow and random.", "3": "Diversity at steady state reflects a speciation–extinction (dispersal) balance, as in the fundamental biodiversity number θ."})),
# C13
Q("C", 1, [P("An enzyme has been found to efficiently catalyse the following reaction:"), P("A ⇌ B &nbsp;&nbsp; (forward rate constant k<sub>f</sub>, reverse rate constant k<sub>r</sub>); K<sub>eq</sub> = k<sub>f</sub> / k<sub>r</sub>"), P("Where k<sub>f</sub>: forward rate of the reaction; k<sub>r</sub>: reverse rate of the reaction; K<sub>eq</sub>: equilibrium constant."), P("Which one of the following parameters will be increased over the uncatalyzed reaction by the enzyme?")],
  ["k<sub>r</sub>", "K<sub>eq</sub>", "1/k<sub>r</sub>", "1/K<sub>eq</sub>"],
  E("A catalyst lowers the activation energy of the transition state shared by both directions. So it increases k<sub>f</sub> and k<sub>r</sub> by the same factor and leaves K<sub>eq</sub> = k<sub>f</sub>/k<sub>r</sub> (and ΔG°) unchanged (principle of microscopic reversibility). Of the listed quantities only k<sub>r</sub> increases.",
    {"2": "Enzymes do not change the equilibrium constant.", "3": "k<sub>r</sub> increases, so 1/k<sub>r</sub> decreases.", "4": "K<sub>eq</sub> is unchanged, so 1/K<sub>eq</sub> is unchanged."})),
